class RWLock:
    def __init__(self): self._cv, self._r, self._w = threading.Condition(), 0, False
    def acquire_read(self):
        with self._cv:
            while self._w: self._cv.wait()
            self._r += 1
    def release_read(self):
        with self._cv:
            self._r -= 1
            if not self._r: self._cv.notify_all()
    def acquire_write(self):                      # release_write mirrors it
        with self._cv:
            while self._w or self._r: self._cv.wait()
            self._w = True
